// n8n Function node: "Validate" (purge)
const src = ($json && $json.body) ? $json.body : $json;
const conversation_id = src.conversation_id;
const tenant_id       = src.tenant_id;
const token           = src.token;

for (const [k, v] of Object.entries({ conversation_id, tenant_id })) {
  if (v === undefined || v === null || String(v).trim() === '') {
    throw new Error(`Missing required field: ${k}`);   // -> 422
  }
}

// Shared-secret auth for this destructive op. Operator replaces __PURGE_TOKEN__
// at import time; until then auth is disabled (localhost-only use).
const EXPECTED = '__PURGE_TOKEN__';
if (EXPECTED !== '__PURGE_TOKEN__') {
  if (!token || String(token) !== EXPECTED) {
    throw new Error('Invalid purge token');   // -> 401
  }
}

return [{ json: { conversation_id: String(conversation_id), tenant_id: String(tenant_id) } }];

// n8n Function node: "Format response" (purge)
// DELETE ... RETURNING id runs with alwaysOutputData:true, so 0 deletions emits
// a single empty item. Count only real rows (have id). 0 is a valid idempotent success.
const rows = items.filter(i => i.json && i.json.id);
const v = $('Validate').first().json;
return [{ json: { status: 'purged', conversation_id: v.conversation_id, deleted_count: rows.length } }];

// n8n Function node: "Format Error" (purge)
const j = items[0].json || {};
const rawErr = (j && j.error && typeof j.error === 'object') ? j.error : j;
const msg =
  (rawErr && (rawErr.message || rawErr.description)) ||
  (typeof j.error === 'string' ? j.error : null) ||
  j.message ||
  'Unexpected error during purge';
const msgStr = String(msg);

const RULES = [
  { re: /Missing required field/i, phase: 'validation', node: 'Validate',         code: 422 },
  { re: /Invalid purge token/i,    phase: 'auth',       node: 'Validate',         code: 401 },
  { re: /DELETE|relation|column|ephemeral_chunks|syntax error/i, phase: 'purge', node: 'Delete ephemeral', code: 500 },
];
const m = RULES.find(r => r.re.test(msgStr));
const phase = m ? m.phase : 'unknown';
const statusCode = m ? m.code : 500;
const errorType = statusCode >= 500 ? 'runtime' : (statusCode === 401 ? 'auth' : 'validation');

let conversation_id = null, tenant_id = null;
try {
  const w = $('Webhook /purge-ephemeral').first().json;
  const b = (w && w.body) ? w.body : w;
  conversation_id = b.conversation_id || null; tenant_id = b.tenant_id || null;
} catch (e) {}

return [{ json: {
  status: 'failed', phase, node: m ? m.node : 'unknown', errorType, statusCode, error: msgStr,
  conversation_id, tenant_id, timestamp: new Date().toISOString(),
}}];
